"""Tiny descriptive statistics: mean, median and mode."""

from collections import Counter


def mean(xs):
    """Return the arithmetic mean of xs. Raises ValueError if xs is empty."""
    xs = list(xs)
    if not xs:
        raise ValueError("mean() requires at least one value")
    return sum(xs) / len(xs)


def median(xs):
    """Return the median of xs, averaging the middle pair for even lengths.

    Raises ValueError if xs is empty. The input is not modified.
    """
    s = sorted(xs)
    n = len(s)
    if not n:
        raise ValueError("median() requires at least one value")
    mid = n // 2
    if n % 2:
        return s[mid]
    return (s[mid - 1] + s[mid]) / 2


def mode(xs):
    """Return the most common value in xs; ties go to the smallest value.

    Raises ValueError if xs is empty.
    """
    counts = Counter(xs)
    if not counts:
        raise ValueError("mode() requires at least one value")
    top = max(counts.values())
    return min(x for x, c in counts.items() if c == top)
